//! ↔️ Original funded paged movements preserve the selected owners and Work receipt.
use semio_framework_value_paged_list::PagedList;
use semio_framework_value_control_contract::{RetainedCloneProgress,RetainedWorkPoll};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
#[test]fn paged_movements_use_original_funding_and_receipt(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("movement-laws.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){let initial:Vec<u64>=serde_json::from_value(row["values"].clone()).unwrap();let expected:Vec<u64>=serde_json::from_value(row["expected"].clone()).unwrap();let mut list:PagedList<u64,64>=initial.iter().copied().collect();let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));let left=row["left"].as_u64().unwrap()as usize;let right=row["right"].as_u64().unwrap()as usize;let demand=list.swap_source_demand(left,right).unwrap();let work=list.swap_source_work_demand(left,right).unwrap();let mut grant=bank.loan(1,demand.copy_bytes);grant.maximum_depth=demand.depth;
  if work>0{for kind in 0..3{let mut denied=grant;match kind{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=demand.copy_bytes-1,_=>denied.maximum_depth=demand.depth-1}let((poll,actual),heap)=observe(||bank.run(denied,work,|effect|RetainedWorkPoll::Complete(list.swap_source_step(left,right,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("swap must settle")};assert!(!turn.result.unwrap());assert_eq!(turn.work,0);assert_eq!(actual,None);assert_eq!(heap,(0,0));assert_eq!(list.iter().copied().collect::<Vec<_>>(),initial);}let((poll,actual),heap)=observe(||bank.run(grant,work-1,|effect|RetainedWorkPoll::Complete(list.swap_source_step(left,right,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("swap must settle")};assert!(!turn.result.unwrap());assert_eq!(turn.work,0);assert_eq!(actual,None);assert_eq!(heap,(0,0));assert_eq!(list.iter().copied().collect::<Vec<_>>(),initial);}
  let((poll,actual),heap)=observe(||bank.run(grant,work,|effect|{assert!(effect.work_source_turn().is_some());RetainedWorkPoll::Complete(list.swap_source_step(left,right,effect))}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("swap must settle")};assert!(turn.result.unwrap());assert_eq!(turn.work,u128::from(work));assert_eq!(actual,None);assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),if work==0{None}else{Some(true)});bank.post(RetainedCloneProgress{copied_items:usize::from(work>0),copied_bytes:demand.copy_bytes,..Default::default()},grant,heap);assert_eq!(list.iter().copied().collect::<Vec<_>>(),expected);
  let demand=list.pop_source_demand().unwrap();let work=list.pop_source_work_demand().unwrap();let mut grant=bank.loan(1,demand.copy_bytes);grant.maximum_depth=demand.depth;let mut output=None;let((poll,actual),heap)=observe(||bank.run(grant,work-1,|effect|RetainedWorkPoll::Complete(list.pop_source_step(&mut output,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("pop must settle")};assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(output,None);assert_eq!(actual,None);assert_eq!(heap,(0,0));let((poll,actual),heap)=observe(||bank.run(grant,work,|effect|RetainedWorkPoll::Complete(list.pop_source_step(&mut output,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("pop must settle")};assert_eq!(turn.work,u128::from(work));let progress=turn.result.unwrap().progress();assert_eq!(output,Some(row["popped"].as_u64().unwrap()));assert_eq!(actual,None);assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,heap);
 }
}
